-- ORSHAP WMS v13.9.58
-- Remove runtime reads of retired shelf zone/section snapshots from receipt/return postings.
-- Include owner dimension in advisory locks to align with owner-scoped stock rows.
BEGIN;
CREATE OR REPLACE FUNCTION public.confirm_stock_transfer_return(p_transfer_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth', 'pg_temp'
AS $function$
                                                DECLARE
                                                  v_user uuid := auth.uid();
                                                    v_profile public.profiles%ROWTYPE;
                                                      v_t public.stock_transfers%ROWTYPE;
                                                        v_src public.shelves%ROWTYPE;
                                                          v_qty numeric;
                                                            v_before numeric := 0;
                                                              v_after numeric;
                                                                v_tx uuid;
                                                                  v_area uuid; v_owner uuid;
                                                                    v_lock_key text;
                                                                      v_status text;
                                                                        v_returned_after numeric;
                                                                          v_resolved numeric;
                                                                            v_order_status text;
                                                                            BEGIN
                                                                              IF v_user IS NULL OR NOT public.current_user_is_active() THEN
                                                                                  RAISE EXCEPTION 'An active authenticated user is required';
                                                                                    END IF;
                                                                                      IF NOT public.current_user_has_permission('action:stock_transfer:receive') THEN
                                                                                          RAISE EXCEPTION 'Permission denied to confirm returned goods';
                                                                                            END IF;

                                                                                              SELECT * INTO v_profile FROM public.profiles WHERE id = v_user AND status = 'ACTIVE';
                                                                                                SELECT * INTO v_t FROM public.stock_transfers WHERE id = p_transfer_id FOR UPDATE;
                                                                                                  IF NOT FOUND THEN RAISE EXCEPTION 'Stock transfer line not found'; END IF;
                                                                                                    IF v_t.status <> 'RETURN_IN_TRANSIT' THEN
                                                                                                        RAISE EXCEPTION 'Only a return-in-transit line can be confirmed';
                                                                                                          END IF;
 IF COALESCE(v_t.return_review_status, 'PENDING') <> 'ACCEPTED' THEN
 RAISE EXCEPTION 'Return request must be accepted before physical receipt';
 END IF;
                                                                                                            IF COALESCE(v_profile.role, '') NOT IN ('SUPER_ADMIN','ADMIN','MANAGER')
                                                                                                                 AND (cardinality(COALESCE(v_profile.assigned_warehouse_ids, ARRAY[]::uuid[])) = 0
                                                                                                                        OR NOT (v_t.source_warehouse_id = ANY(v_profile.assigned_warehouse_ids))) THEN
                                                                                                                            RAISE EXCEPTION 'User is not assigned to the sending warehouse';
                                                                                                                              END IF;

                                                                                                                                v_qty := COALESCE(v_t.return_requested_quantity, 0) - COALESCE(v_t.returned_quantity, 0);
                                                                                                                                  IF v_qty <= 0 THEN RAISE EXCEPTION 'No return quantity remains to be confirmed'; END IF;

                                                                                                                                    SELECT * INTO v_src FROM public.shelves
                                                                                                                                       WHERE id = v_t.source_shelf_id AND warehouse_id = v_t.source_warehouse_id;
                                                                                                                                         IF NOT FOUND THEN RAISE EXCEPTION 'Source shelf is no longer valid'; END IF;

                                                                                                                                           v_area := v_src.storage_area_id;
                                                                                                                                                       v_owner := v_t.administrative_department_id; IF v_owner IS NULL OR NOT EXISTS (SELECT 1 FROM public.administrative_departments d WHERE d.id=v_owner AND d.is_active=true) THEN RAISE EXCEPTION 'Transfer owner is missing or inactive; return receipt cannot be posted'; END IF; v_lock_key := v_t.item_id::text || ':' || v_t.source_shelf_id::text || ':' || COALESCE(v_t.batch_no, '') || ':' || v_owner::text;
                                                                                                                                                         PERFORM pg_advisory_xact_lock(hashtextextended(v_lock_key, 0));

                                                                                                                                                           SELECT quantity INTO v_before FROM public.stock
                                                                                                                                                              WHERE item_id = v_t.item_id AND shelf_id = v_t.source_shelf_id AND batch_no = COALESCE(v_t.batch_no, '') AND administrative_department_id = v_owner
                                                                                                                                                                 FOR UPDATE;
                                                                                                                                                                   v_before := COALESCE(v_before, 0);
                                                                                                                                                                     v_after := v_before + v_qty;
                                                                                                                                                                       v_tx := gen_random_uuid();

                                                                                                                                                                         INSERT INTO public.transactions
                                                                                                                                                                             (id, reference_no, transaction_type, status, warehouse_id, zone_id, section_id,
                                                                                                                                                                                  storage_area_id, notes, created_by)
                                                                                                                                                                                    VALUES
                                                                                                                                                                                        (v_tx, v_t.reference_no || '-RET-RCV', 'TRANSFER_RETURN', 'APPROVED',
                                                                                                                                                                                             v_src.warehouse_id, NULL, NULL, v_area,
                                                                                                                                                                                                  'Returned transfer quantity physically received by source. Reason: ' || COALESCE(v_t.return_reason, ''), v_user);

                                                                                                                                                                                                    INSERT INTO public.transaction_lines
                                                                                                                                                                                                        (transaction_id, item_id, shelf_id, administrative_department_id, quantity, balance_before, balance_after,
                                                                                                                                                                                                             batch_no, expiry_date, storage_area_id, notes)
                                                                                                                                                                                                               VALUES
                                                                                                                                                                                                                   (v_tx, v_t.item_id, v_t.source_shelf_id, v_owner, v_qty, v_before, v_after,
                                                                                                                                                                                                                        v_t.batch_no, v_t.expiry_date, v_area,
                                                                                                                                                                                                                             'Transfer=' || p_transfer_id::text || '; direction=RETURN_RECEIVED; reason=' || COALESCE(v_t.return_reason, ''));

                                                                                                                                                                                                                               INSERT INTO public.stock
                                                                                                                                                                                                                                   (item_id, shelf_id, administrative_department_id, quantity, batch_no, expiry_date, storage_area_id, updated_at)
                                                                                                                                                                                                                                     VALUES
                                                                                                                                                                                                                                         (v_t.item_id, v_t.source_shelf_id, v_owner, v_after, COALESCE(v_t.batch_no, ''), v_t.expiry_date, v_area, now())
                                                                                                                                                                                                                                           ON CONFLICT (item_id, shelf_id, batch_no, administrative_department_id) DO UPDATE
                                                                                                                                                                                                                                               SET quantity = EXCLUDED.quantity,
                                                                                                                                                                                                                                                       expiry_date = COALESCE(EXCLUDED.expiry_date, public.stock.expiry_date),
                                                                                                                                                                                                                                                               storage_area_id = COALESCE(EXCLUDED.storage_area_id, public.stock.storage_area_id),
                                                                                                                                                                                                                                                                       updated_at = now();

                                                                                                                                                                                                                                                                         PERFORM public.log_transaction_ledger(
                                                                                                                                                                                                                                                                             p_transaction_id := v_tx,
                                                                                                                                                                                                                                                                                 p_ledger_type := 'STOCK_TRANSFER',
                                                                                                                                                                                                                                                                                     p_user_id := v_user,
                                                                                                                                                                                                                                                                                         p_warehouse_id := v_src.warehouse_id,
                                                                                                                                                                                                                                                                                             p_zone_id := NULL::uuid,
                                                                                                                                                                                                                                                                                                 p_section_id := NULL::uuid,
                                                                                                                                                                                                                                                                                                     p_shelf_id := v_t.source_shelf_id,
                                                                                                                                                                                                                                                                                                         p_item_id := v_t.item_id,
                                                                                                                                                                                                                                                                                                             p_quantity := v_qty,
                                                                                                                                                                                                                                                                                                                 p_balance_before := v_before,
                                                                                                                                                                                                                                                                                                                     p_balance_after := v_after,
                                                                                                                                                                                                                                                                                                                         p_transaction_type := 'TRANSFER_RETURN',
                                                                                                                                                                                                                                                                                                                             p_details := jsonb_build_object('transfer_id', p_transfer_id, 'order_id', v_t.transfer_order_id,
                                                                                                                                                                                                                                                                                                                                   'returned_quantity', v_qty, 'reason', v_t.return_reason, 'batch_no', v_t.batch_no, 'administrative_department_id', v_owner),
                                                                                                                                                                                                                                                                                                                                       p_reference := v_t.reference_no,
                                                                                                                                                                                                                                                                                                                                           p_approved := true,
                                                                                                                                                                                                                                                                                                                                               p_reference_type := 'STOCK_TRANSFER_RETURN_RECEIPT',
                                                                                                                                                                                                                                                                                                                                                   p_batch_no := v_t.batch_no,
                                                                                                                                                                                                                                                                                                                                                       p_expiry_date := v_t.expiry_date
                                                                                                                                                                                                                                                                                                                                                         );

                                                                                                                                                                                                                                                                                                                                                           v_returned_after := COALESCE(v_t.returned_quantity, 0) + v_qty;
                                                                                                                                                                                                                                                                                                                                                             v_resolved := COALESCE(v_t.received_quantity, 0) + v_returned_after;
                                                                                                                                                                                                                                                                                                                                                               v_status := CASE
                                                                                                                                                                                                                                                                                                                                                                   WHEN v_resolved < v_t.quantity THEN
                                                                                                                                                                                                                                                                                                                                                                         CASE WHEN COALESCE(v_t.received_quantity, 0) > 0 THEN 'PARTIALLY_RECEIVED' ELSE 'IN_TRANSIT' END
                                                                                                                                                                                                                                                                                                                                                                             WHEN v_returned_after > 0 AND COALESCE(v_t.received_quantity, 0) = 0 THEN 'RETURNED_TO_SOURCE'
                                                                                                                                                                                                                                                                                                                                                                                 WHEN v_returned_after > 0 AND COALESCE(v_t.received_quantity, 0) > 0 THEN 'PARTIALLY_RETURNED'
                                                                                                                                                                                                                                                                                                                                                                                     WHEN COALESCE(v_t.received_quantity, 0) >= v_t.quantity THEN 'RECEIVED'
                                                                                                                                                                                                                                                                                                                                                                                         ELSE 'REJECTED'
                                                                                                                                                                                                                                                                                                                                                                                           END;

                                                                                                                                                                                                                                                                                                                                                                                             UPDATE public.stock_transfers
                                                                                                                                                                                                                                                                                                                                                                                                  SET returned_quantity = v_returned_after,
                                                                                                                                                                                                                                                                                                                                                                                                           return_confirmed_by = v_user,
                                                                                                                                                                                                                                                                                                                                                                                                                    return_confirmed_at = now(),
                                                                                                                                                                                                                                                                                                                                                                                                                             return_transaction_id = v_tx,
                                                                                                                                                                                                                                                                                                                                                                                                                                      status = v_status,
                                                                                                                                                                                                                                                                                                                                                                                                                                               updated_at = now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                  WHERE id = p_transfer_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                    PERFORM public.finalize_stock_transfer_source_issue(p_transfer_id, v_user);

                                                                                                                                                                                                                                                                                                                                                                                                                                                      SELECT CASE
                                                                                                                                                                                                                                                                                                                                                                                                                                                          WHEN EXISTS (SELECT 1 FROM public.stock_transfers st WHERE st.transfer_order_id = v_t.transfer_order_id AND st.status = 'RETURN_IN_TRANSIT') THEN 'RETURN_IN_TRANSIT'
                                                                                                                                                                                                                                                                                                                                                                                                                                                              WHEN EXISTS (SELECT 1 FROM public.stock_transfers st WHERE st.transfer_order_id = v_t.transfer_order_id AND st.status = 'IN_TRANSIT') THEN 'IN_TRANSIT'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  WHEN EXISTS (SELECT 1 FROM public.stock_transfers st WHERE st.transfer_order_id = v_t.transfer_order_id AND st.status = 'PARTIALLY_RECEIVED') THEN 'PARTIALLY_RECEIVED'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      WHEN EXISTS (SELECT 1 FROM public.stock_transfers st WHERE st.transfer_order_id = v_t.transfer_order_id AND st.status = 'PARTIALLY_RETURNED') THEN 'PARTIALLY_RETURNED'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          WHEN EXISTS (SELECT 1 FROM public.stock_transfers st WHERE st.transfer_order_id = v_t.transfer_order_id AND st.status = 'RETURNED_TO_SOURCE')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                AND NOT EXISTS (SELECT 1 FROM public.stock_transfers st WHERE st.transfer_order_id = v_t.transfer_order_id AND st.status <> 'RETURNED_TO_SOURCE') THEN 'RETURNED_TO_SOURCE'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    WHEN EXISTS (SELECT 1 FROM public.stock_transfers st WHERE st.transfer_order_id = v_t.transfer_order_id AND st.status = 'RETURNED_TO_SOURCE') THEN 'PARTIALLY_RETURNED'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        WHEN NOT EXISTS (SELECT 1 FROM public.stock_transfers st WHERE st.transfer_order_id = v_t.transfer_order_id AND st.status NOT IN ('RECEIVED','COMPLETED')) THEN 'RECEIVED'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ELSE 'REJECTED'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              END INTO v_order_status;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                UPDATE public.stock_transfer_orders
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     SET status = v_order_status, updated_at = now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        WHERE id = v_t.transfer_order_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          INSERT INTO public.audit_logs
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              (user_id, action, entity, entity_id, warehouse_id, reference, details)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                VALUES
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    (v_user, 'STOCK_TRANSFER_RETURN_RECEIVED', 'STOCK_TRANSFER', p_transfer_id::text,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         v_src.warehouse_id, v_t.reference_no,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              jsonb_build_object('order_id', v_t.transfer_order_id, 'quantity', v_qty,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     'balance_before', v_before, 'balance_after', v_after, 'reason', v_t.return_reason,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'line_status', v_status, 'order_status', v_order_status)::text);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              RETURN jsonb_build_object('success', true, 'transfer_id', p_transfer_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'returned_quantity', v_qty, 'source_balance_after', v_after,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'status', v_status, 'order_status', v_order_status);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      END;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      $function$
;
CREATE OR REPLACE FUNCTION public.receive_stock_transfer_quantity_at_shelf_v2(p_transfer_id uuid, p_received_quantity numeric, p_destination_shelf_id uuid, p_return_remaining boolean, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_user uuid:=auth.uid(); v_profile public.profiles%ROWTYPE; v_t public.stock_transfers%ROWTYPE;
  v_dst public.shelves%ROWTYPE; v_before numeric:=0; v_after numeric; v_tx uuid; v_area uuid; v_owner uuid;
  v_outstanding numeric; v_return numeric:=0; v_lock_key text; v_status text;
BEGIN
  IF v_user IS NULL OR NOT public.current_user_is_active() THEN RAISE EXCEPTION 'An active authenticated user is required'; END IF;
  IF NOT public.current_user_has_permission('action:stock_transfer:receive') THEN RAISE EXCEPTION 'Permission denied to receive stock transfers'; END IF;
  IF p_received_quantity IS NULL OR p_received_quantity<0 OR p_received_quantity::text IN ('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'Received quantity must be zero or greater'; END IF;
  IF p_return_remaining AND NULLIF(btrim(COALESCE(p_reason,'')),'') IS NULL THEN RAISE EXCEPTION 'A reason is required when requesting return of the remainder'; END IF;
  IF NOT p_return_remaining AND p_received_quantity=0 THEN RAISE EXCEPTION 'Enter a received quantity or request return of the remainder'; END IF;
  SELECT * INTO v_profile FROM public.profiles WHERE id=v_user AND status='ACTIVE';
  SELECT * INTO v_t FROM public.stock_transfers WHERE id=p_transfer_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Stock transfer line not found'; END IF;
  IF COALESCE(v_t.received_quantity,0)>0 AND p_destination_shelf_id IS NOT NULL AND p_destination_shelf_id IS DISTINCT FROM v_t.destination_shelf_id THEN
    RAISE EXCEPTION 'A partial receipt already exists; subsequent receipts must use the same destination shelf';
  END IF;
  IF p_received_quantity>0 THEN v_t.destination_shelf_id:=COALESCE(p_destination_shelf_id,v_t.destination_shelf_id); END IF;
  v_t.destination_shelf_id := COALESCE(p_destination_shelf_id, v_t.destination_shelf_id);
  IF v_t.destination_shelf_id IS NULL THEN
    RAISE EXCEPTION 'A destination shelf is required for receipt';
  END IF;
  IF v_t.status NOT IN ('IN_TRANSIT','PARTIALLY_RECEIVED') THEN RAISE EXCEPTION 'Only an in-transit line can be reconciled'; END IF;
  v_owner:=v_t.administrative_department_id;
  IF v_owner IS NULL OR NOT EXISTS (SELECT 1 FROM public.administrative_departments d WHERE d.id=v_owner AND d.is_active=true) THEN RAISE EXCEPTION 'Transfer owner is missing or inactive; receipt cannot be posted'; END IF;
  IF COALESCE(v_profile.role,'') NOT IN ('SUPER_ADMIN','ADMIN','MANAGER') AND (cardinality(COALESCE(v_profile.assigned_warehouse_ids,ARRAY[]::uuid[]))=0 OR NOT(v_t.destination_warehouse_id=ANY(v_profile.assigned_warehouse_ids))) THEN RAISE EXCEPTION 'User is not assigned to the destination warehouse'; END IF;
  v_outstanding:=v_t.quantity-COALESCE(v_t.received_quantity,0)-COALESCE(v_t.returned_quantity,0);
  IF v_outstanding<=0 THEN RAISE EXCEPTION 'No quantity remains outstanding'; END IF;
  IF p_received_quantity>v_outstanding THEN RAISE EXCEPTION 'Received quantity exceeds outstanding quantity'; END IF;
  IF p_return_remaining THEN v_return:=v_outstanding-p_received_quantity; END IF;
  IF p_received_quantity=0 AND v_return=0 THEN RAISE EXCEPTION 'No receipt or return quantity was entered'; END IF;
  IF p_received_quantity>0 THEN
    SELECT * INTO v_dst FROM public.shelves WHERE id=COALESCE(p_destination_shelf_id,v_t.destination_shelf_id) AND warehouse_id=v_t.destination_warehouse_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Choose a valid destination shelf for received stock'; END IF;
    v_t.destination_shelf_id:=v_dst.id;
    v_area:=v_dst.storage_area_id;
  END IF;
  IF p_received_quantity>0 THEN
    v_lock_key:=v_t.item_id::text||':'||v_t.destination_shelf_id::text||':'||v_t.batch_no||':'||v_owner::text;
    PERFORM pg_advisory_xact_lock(hashtextextended(v_lock_key,0));
    SELECT quantity INTO v_before FROM public.stock WHERE item_id=v_t.item_id AND shelf_id=v_t.destination_shelf_id AND batch_no=COALESCE(v_t.batch_no,'') AND administrative_department_id=v_owner FOR UPDATE;
    v_before:=COALESCE(v_before,0); v_after:=v_before+p_received_quantity; v_tx:=gen_random_uuid();
    INSERT INTO public.transactions(id,reference_no,transaction_type,status,warehouse_id,zone_id,section_id,storage_area_id,notes,created_by)
    VALUES(v_tx,v_t.reference_no||'-RCV-'||COALESCE(v_t.received_quantity,0)::text,'TRANSFER_IN','APPROVED',v_dst.warehouse_id,NULL,NULL,v_area,COALESCE(v_t.notes,'Inter-warehouse transfer receipt'),v_user);
    INSERT INTO public.transaction_lines(transaction_id,item_id,shelf_id,administrative_department_id,quantity,balance_before,balance_after,batch_no,expiry_date,storage_area_id,notes)
    VALUES(v_tx,v_t.item_id,v_t.destination_shelf_id,v_owner,p_received_quantity,v_before,v_after,COALESCE(v_t.batch_no,''),v_t.expiry_date,v_area,'Transfer='||p_transfer_id::text||'; direction=RECEIPT; actual='||p_received_quantity::text);
    INSERT INTO public.stock(item_id,shelf_id,administrative_department_id,quantity,batch_no,expiry_date,storage_area_id,updated_at)
    VALUES(v_t.item_id,v_t.destination_shelf_id,v_owner,v_after,COALESCE(v_t.batch_no,''),v_t.expiry_date,v_area,now())
    ON CONFLICT (item_id, shelf_id, batch_no, administrative_department_id) DO UPDATE SET quantity=EXCLUDED.quantity,expiry_date=COALESCE(EXCLUDED.expiry_date,public.stock.expiry_date),storage_area_id=COALESCE(EXCLUDED.storage_area_id,public.stock.storage_area_id),updated_at=now();
    PERFORM public.log_transaction_ledger(p_transaction_id:=v_tx,p_ledger_type:='STOCK_TRANSFER',p_user_id:=v_user,p_warehouse_id:=v_dst.warehouse_id,p_zone_id:=NULL::uuid,p_section_id:=NULL::uuid,p_shelf_id:=v_t.destination_shelf_id,p_item_id:=v_t.item_id,p_quantity:=p_received_quantity,p_balance_before:=v_before,p_balance_after:=v_after,p_transaction_type:='TRANSFER_IN',p_details:=jsonb_build_object('transfer_id',p_transfer_id,'order_id',v_t.transfer_order_id,'source_warehouse_id',v_t.source_warehouse_id,'batch_no',v_t.batch_no,'received_quantity',p_received_quantity,'administrative_department_id',v_owner),p_reference:=v_t.reference_no,p_approved:=true,p_reference_type:='STOCK_TRANSFER_RECEIPT',p_batch_no:=v_t.batch_no,p_expiry_date:=v_t.expiry_date);
  END IF;
  v_status:=CASE WHEN v_return>0 THEN 'RETURN_IN_TRANSIT' WHEN COALESCE(v_t.received_quantity,0)+p_received_quantity>=v_t.quantity THEN 'RECEIVED' WHEN COALESCE(v_t.received_quantity,0)+p_received_quantity>0 THEN 'PARTIALLY_RECEIVED' ELSE 'IN_TRANSIT' END;
  UPDATE public.stock_transfers SET destination_shelf_id=CASE WHEN p_received_quantity>0 THEN COALESCE(p_destination_shelf_id,destination_shelf_id) ELSE destination_shelf_id END,received_quantity=COALESCE(received_quantity,0)+p_received_quantity,return_requested_quantity=COALESCE(return_requested_quantity,0)+v_return,return_reason=CASE WHEN v_return>0 THEN btrim(p_reason) ELSE return_reason END,return_requested_by=CASE WHEN v_return>0 THEN v_user ELSE return_requested_by END,return_requested_at=CASE WHEN v_return>0 THEN now() ELSE return_requested_at END,receipt_notes=concat_ws(E'\n',NULLIF(receipt_notes,''),CASE WHEN p_received_quantity>0 THEN 'Physically received: '||p_received_quantity::text END,CASE WHEN v_return>0 THEN 'Return requested: '||v_return::text||'; reason: '||btrim(p_reason) END),received_by=CASE WHEN p_received_quantity>0 THEN v_user ELSE received_by END,received_at=CASE WHEN p_received_quantity>0 THEN now() ELSE received_at END,destination_transaction_id=COALESCE(v_tx,destination_transaction_id),status=v_status,updated_at=now() WHERE id=p_transfer_id;
  PERFORM public.finalize_stock_transfer_source_issue(p_transfer_id,v_user);
  UPDATE public.stock_transfer_orders o SET status=CASE WHEN EXISTS(SELECT 1 FROM public.stock_transfers st WHERE st.transfer_order_id=o.id AND st.status='RETURN_IN_TRANSIT') THEN 'RETURN_IN_TRANSIT' WHEN EXISTS(SELECT 1 FROM public.stock_transfers st WHERE st.transfer_order_id=o.id AND st.status IN ('IN_TRANSIT','PARTIALLY_RECEIVED')) THEN CASE WHEN EXISTS(SELECT 1 FROM public.stock_transfers st WHERE st.transfer_order_id=o.id AND st.status='PARTIALLY_RECEIVED') THEN 'PARTIALLY_RECEIVED' ELSE 'IN_TRANSIT' END WHEN EXISTS(SELECT 1 FROM public.stock_transfers st WHERE st.transfer_order_id=o.id AND st.status='PARTIALLY_RECEIVED') THEN 'PARTIALLY_RECEIVED' WHEN EXISTS(SELECT 1 FROM public.stock_transfers st WHERE st.transfer_order_id=o.id AND st.status='RECEIVED') THEN 'RECEIVED' ELSE 'REJECTED' END,updated_at=now() WHERE o.id=v_t.transfer_order_id;
  INSERT INTO public.audit_logs(user_id,action,entity,entity_id,warehouse_id,reference,details)
  VALUES(v_user,'STOCK_TRANSFER_RECEIPT_RECONCILED','STOCK_TRANSFER',p_transfer_id::text,v_dst.warehouse_id,v_t.reference_no,jsonb_build_object('order_id',v_t.transfer_order_id,'sent',v_t.quantity,'received_now',p_received_quantity,'return_requested',v_return,'reason',p_reason,'status',v_status)::text);
  RETURN jsonb_build_object('success',true,'transfer_id',p_transfer_id,'order_id',v_t.transfer_order_id,'received_now',p_received_quantity,'return_requested',v_return,'remaining_in_transit',v_outstanding-p_received_quantity-v_return,'status',v_status);
END;
$function$
;
COMMIT;